package com.gameaggregator.billingservice.api;import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.*;import java.util.UUID;public final class BillingDtos{private BillingDtos(){}public record Plan(@NotBlank String code,@Pattern(regexp="MONTHLY|QUARTERLY|ANNUAL")String cycle,@Positive long usageQuota,@Positive BigDecimal price,@Pattern(regexp="[A-Z]{3}")String currency){}public record Usage(@NotBlank String idempotencyKey,@NotNull UUID clientId,@Positive long quantity,@NotNull Instant occurredAt){}public record InvoiceRequest(@NotBlank String invoiceNumber,@NotNull UUID clientId,@NotNull LocalDate cycleFrom,@NotNull LocalDate cycleTo,@PositiveOrZero BigDecimal total,@Pattern(regexp="[A-Z]{3}")String currency){}public record Item(@NotBlank String description,@Positive long quantity,@PositiveOrZero BigDecimal unitPrice){}public record Credit(@Positive BigDecimal amount,@NotBlank String reason){}public record Payment(@Pattern(regexp="UNPAID|PENDING|PAID|FAILED|REFUNDED")String status){}}